p=root/'frontend/css/role-dashboard.css';s=p.read_text()+'''\n/* v4 dashboard hardening */\n.dashboard-loading{min-height:220px;display:flex;align-items:center;justify-content:center;gap:16px}.dashboard-loading[hidden]{display:none}.admin-toolbar{align-items:stretch}.admin-select{max-width:180px;padding:0 10px}.pagination-bar{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid var(--border-light);margin-top:14px;padding-top:14px;color:var(--text-muted);font-size:13px}.pagination-bar>div{display:flex;gap:8px}.presence{display:inline-flex;align-items:center;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:800;background:var(--surface-alt)}.presence.online{color:var(--success);background:var(--success-bg)}.presence.away{color:var(--warning);background:var(--warning-bg)}.presence.offline{color:var(--text-muted)}.verification-panel{display:flex;flex-direction:column;gap:10px}.approval-card{padding:16px;border:1px solid var(--border-light);border-radius:14px;background:var(--surface-alt);margin-bottom:10px}.approval-head{display:flex;justify-content:space-between;gap:12px}.approval-title{font-weight:800}.approval-meta{color:var(--text-muted);font-size:12px;margin-top:4px}.approval-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.document-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--border-light)}.drawer-section{padding:16px 0}.audit-item{padding:12px 0;border-bottom:1px solid var(--border-light)}.audit-action{font-weight:750}.audit-meta{font-size:12px;color:var(--text-muted);margin-top:4px}.small-muted{font-size:12px;color:var(--text-muted)}@media(max-width:900px){.span-8,.span-7,.span-6,.span-5,.span-4{grid-column:span 12}.action-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.admin-toolbar .search-input{max-width:none;flex:1 1 100%}.admin-select{max-width:none}.pagination-bar{align-items:flex-start;flex-direction:column}}@media(max-width:560px){.role-dashboard{padding:18px 14px 90px}.action-grid{grid-template-columns:1fr}.detail-grid,.vitals-strip{grid-template-columns:1fr 1fr}.list-row,.approval-head{align-items:flex-start;flex-direction:column}.list-actions{justify-content:flex-start;width:100%}.btn-small{min-height:44px}.pagination-bar>div{width:100%}.pagination-bar .btn-small{flex:1}}\n''';p.write_text(s)
